refentry.refsect1:
&reftitle.description;

 public boolYaf_Request_Abstract::isOptions


Verifica se a requisição foi enviada com o método OPTIONS.

  &reftitle.examples;

   Exemplo de Yaf_Request_Abstract::isOptions


<?php
class ApiController extends Yaf_Controller_Abstract
{
    public function corsAction()
    {
        // Supondo que o navegador envie uma requisição de verificação prévia CORS
        if ($this->getRequest()->isOptions()) {
            $this->getResponse()
                 ->setHeader("Allow", "GET, POST, OPTIONS")
                 ->setBody("");
            return false;
        }
    }
}
?>
